/* ---- 2 linh vật game xếp thẻ: Mèo Đen Bí Ngô (Ghép Ba Thẻ), Thỏ Hoa (Tìm Đôi Thẻ) ---- */
const pumpkin = (x, y, s = 1) => `<g transform="translate(${x} ${y}) scale(${s})"><ellipse cx="0" cy="0" rx="9" ry="7.5" fill="#FF8A1F"/><path d="M-4 -6Q-6 0 -4 6M4 -6Q6 0 4 6" fill="none" stroke="#C85A00" stroke-width="1.6"/><path d="M0 -7V-12" stroke="#3E8E2E" stroke-width="3" stroke-linecap="round"/></g>`;
const flower = (x, y, s = 1, p = "#fff", c = "#FFC83D") => `<g transform="translate(${x} ${y}) scale(${s})">${[0, 72, 144, 216, 288].map(a => `<circle cx="${(Math.sin(a * Math.PI / 180) * 6).toFixed(1)}" cy="${(-Math.cos(a * Math.PI / 180) * 6).toFixed(1)}" r="4.6" fill="${p}"/>`).join("")}<circle cx="0" cy="0" r="3.4" fill="${c}"/></g>`;
const tile = (x, y, inner, st) => `<rect x="${x}" y="${y}" width="30" height="34" rx="8" fill="#fff" stroke="${st}" stroke-width="3"/>${inner}`;
